        "bookId": "DEU",
        "bookName": "Deuteronomy",
        "chapterNumber": 7,
        "verseNumber": 9,
        "text": "Know therefore that Yahweh your God himself is God, the faithful God, who keeps covenant and loving kindness with them who love him and keep his commandments to a thousand generations,",
